Create getUser.ts containing exactly this TypeScript, then add comments as you would for a real review:

export type UserId = string & { readonly brand: 'UserId' };
export type User = { id: UserId; email: string };

const cache = new Map<UserId, User>();

export async function getUser(id: UserId): Promise<User | null> {
  const cached = cache.get(id);
  if (cached) return cached;
  const row = await db.users.findById(id);
  if (!row) return null;
  cache.set(id, row);
  return row;
}

// assume db exists
declare const db: { users: { findById(id: UserId): Promise<User | null> } };

Do not change the behavior.

