export type Role = { id: string; name: string };

const ALLOWED_ROLES: Role[] = [
  { id: 'admin', name: 'Admin' },
  { id: 'member', name: 'Member' },
  { id: 'guest', name: 'Guest' }
];

export function roleById(id: string): Role | undefined {
  const byId = new Map(ALLOWED_ROLES.map((role) => [role.id, role]));
  return byId.get(id);
}

